<?php
declare(strict_types=1);
require dirname(__DIR__) . '/src/bootstrap.php';
require dirname(__DIR__) . '/src/advertising.php';
$root = sys_get_temp_dir() . '/allin-image-test-' . bin2hex(random_bytes(10));
$environment = ['APP_ENV' => 'test', 'ADVERTISING_DIRECTORY' => $root, 'ADVERTISING_SIGNING_SECRET' => str_repeat('i', 64)];
$checks = 0;
$check = static function (bool $value, string $label) use (&$checks): void { if (!$value) throw new RuntimeException($label); $checks++; };
$fails = static function (callable $fn) use ($check): void { try { $fn(); } catch (Throwable $e) { $check(true, 'Failure caught'); return; } throw new RuntimeException('Expected rejection.'); };
if (!function_exists('imagecreatetruecolor')) throw new RuntimeException('Run isolated JPEG tests with PHP -d extension=gd.');
$canvas = imagecreatetruecolor(1024, 1024); ob_start(); imagejpeg($canvas, null, 75); $jpeg = ob_get_clean(); imagedestroy($canvas);
$encoded = base64_encode($jpeg); $now = time();
try {
    $check(advertImageBytes($encoded, '1024x1024')[1] === 1024, 'JPEG dimensions');
    $fails(fn() => advertImageBytes(base64_encode('<svg>bad</svg>'), '1024x1024'));
    $fails(fn() => advertImageBytes($encoded, '1536x1024'));
    $fails(fn() => advertImageBytes(substr($encoded, 0, -8), '1024x1024'));
    $c = advertDefaultConfig(); $c['image']['enabled'] = true;
    $check(advertValidateConfig($c)['image']['complexity'] === 'medium', 'Image controls validated');
    $bad = $c; $bad['image']['model'] = 'arbitrary'; $fails(fn() => advertValidateConfig($bad));
    $check(advertJobTimeout(array_replace($c, ['generation' => array_replace($c['generation'], ['timeoutSeconds' => 45]), 'review' => array_replace($c['review'], ['enabled' => true])])) === 312, 'Whole maximum envelope312s');
    advertTransaction($environment, static function (array &$s) use ($now): void {
        $s['config']['enabled'] = true; $s['config']['image']['enabled'] = true; $s['config']['image']['size'] = '1024x1024';
        $s['config']['prices']['checkedAt'] = gmdate('Y-m-d', $now);
        foreach ($s['config']['budget'] as &$cap) $cap = 10000000; unset($cap);
        $s['draft'] = $s['config'];
    });
    $job = advertClaimJob($environment, true, $now);
    $image = advertTransaction($environment, static function (array &$s) use ($environment, $job, $now, $encoded): array {
        advertMachineMutation($s, $job + ['action' => 'begin'], $now);
        advertMachineMutation($s, $job + ['action' => 'settle', 'usage' => ['inputTokens' => 100, 'outputTokens' => 100]], $now);
        $grant = advertMachineMutation($s, ['action' => 'image-grant'] + $job, $now)['grantId'];
        $body = ['jobId' => $job['jobId'], 'fence' => $job['fence'], 'grantId' => $grant];
        advertMachineMutation($s, ['action' => 'begin'] + $body, $now);
        advertMachineMutation($s, ['action' => 'settle', 'usage' => ['textInputTokens' => 100, 'imageInputTokens' => 0, 'imageOutputTokens' => 10, 'textOutputTokens' => 0]] + $body, $now);
        return advertStoreImage($environment, $s, ['data' => $encoded] + $body, $now)['image'];
    });
    $file = $root . '/assets/' . $image['id'] . '.jpg'; $check(is_file($file), 'Fenced uploaded asset persists under lease');
    $state = advertGetAdmin($environment); $counter = array_values($state['usage'])[0];
    $check($counter['images'] === 1 && $counter['imageTokens'] === 110, 'Separate image counts and observed tokens');
    $feature = $job['feature'];
    $payload = ['featureId' => $feature['id'], 'ctaId' => $feature['ctaId'], 'format' => 'headline', 'headline' => 'A quieter everyday moment', 'message' => $feature['facts'][0]['text'], 'scenario' => '', 'items' => [], 'factIds' => [$feature['facts'][0]['id']], 'imageBrief' => 'Editorial visual storytelling with a simple everyday object in warm light and clear breathing room.', 'composition' => 'poster'];
    foreach (['poster', 'split', 'image-led'] as $layout) $check(advertValidPayload(array_replace($payload, ['composition' => $layout]), $feature, $c)['composition'] === $layout, 'Finite composition accepted');
    $fails(fn() => advertValidPayload(array_replace($payload, ['composition' => 'custom-css']), $feature, $c));
    $fails(fn() => advertValidPayload(array_replace($payload, ['headline' => 'A little more room for everyday life']), $feature, $c));
    $check(advertValidPayload(array_replace($payload, ['headline' => "Don't rush. Make head-space."]), $feature, $c)['composition'] === 'poster', 'Hyphen/apostrophe word counting agrees with Node');
    $twoWords = $c; $twoWords['image']['maxHeadlineWords'] = 2;
    $check(advertValidPayload(array_replace($payload, ['headline' => 'Everyday, easier.']), $feature, $twoWords)['composition'] === 'poster', 'Explicit two-word operator maximum remains usable');
    advertFinishJob($environment, $job, ['status' => 'ready', 'payload' => $payload, 'imageId' => $image['id']], $now);
    $state = advertGetAdmin($environment); $check($state['candidate']['image']['id'] === $image['id'], 'Candidate paired only with current lease upload');
    $orphan = $root . '/assets/' . str_repeat('c', 48) . '.jpg';
    $fails(fn() => advertTransaction($environment, static function (array &$s) use ($orphan, $jpeg): void { $s['candidate'] = null; file_put_contents($orphan, $jpeg); throw new RuntimeException('Synthetic interrupted state commit'); }));
    $check(is_file($file), 'Interrupted metadata commit never deletes still-referenced candidate image');
    $state = advertGetAdmin($environment); $check($state['candidate']['image']['id'] === $image['id'] && !is_file($orphan), 'Prior pair retained and crash orphan cleaned on next committed transaction');
    advertAdminAction($environment, ['action' => 'reject', 'version' => $state['version'], 'candidateId' => $state['candidate']['id']], $now, 42);
    $check(!is_file($file), 'Rejected candidate asset removed after state commit');
    $orphan = $root . '/assets/' . str_repeat('a', 48) . '.jpg'; file_put_contents($orphan, $jpeg);
    advertGetAdmin($environment); $check(!is_file($orphan), 'Unreferenced crash orphan swept');
    $stale = $job; $stale['grantId'] = str_repeat('b', 32);
    $fails(fn() => advertTransaction($environment, static function (array &$s) use ($environment, $stale, $encoded, $now): void { advertStoreImage($environment, $s, ['data' => $encoded] + $stale, $now); }));
    $state = advertInitialState(); $state['config']['image']['enabled'] = true; foreach ($state['config']['budget'] as &$cap) $cap = 10000000; unset($cap);
    $state['config']['prices']['checkedAt'] = gmdate('Y-m-d', $now);
    $reservation = advertReserveCall($state, 'image', $now);
    $check($reservation['micros'] === 2000000 && $reservation['tokens'] === 0 && $reservation['images'] === 1, 'Estimate reservation with no invented token ceiling');
    advertSettleCall($state, ['kind' => 'image', 'reservation' => $reservation], null);
    $check(array_values($state['usage'])[0]['micros'] === 2000000, 'Unknown image outcome retains estimate');
    $legacy = advertInitialState(); $legacy['schema'] = 1; unset($legacy['config']['image'], $legacy['draft']['image'], $legacy['config']['budget']['dailyImages'], $legacy['config']['budget']['monthlyImages'], $legacy['draft']['budget']['dailyImages'], $legacy['draft']['budget']['monthlyImages']);
    $legacy['usage'] = ['d:' . gmdate('Y-m-d') => ['micros' => 366, 'calls' => 2, 'tokens' => 1118]];
    file_put_contents($root . '/state.json', json_encode($legacy));
    $upgraded = advertGetAdmin($environment);
    $check(!$upgraded['config']['image']['enabled'] && array_values($upgraded['usage'])[0]['tokens'] === 1118, 'Legacy migration preserves usage, images disabled');
    $partial = advertInitialState(); $partial['schema'] = 2;
    unset($partial['config']['image']['complexity'], $partial['draft']['image']['complexity'], $partial['config']['image']['layouts'], $partial['draft']['image']['layouts'], $partial['config']['image']['maxHeadlineWords'], $partial['draft']['image']['maxHeadlineWords']);
    $oldPayload = $payload; unset($oldPayload['composition']);
    $partial['current'] = ['id' => str_repeat('d', 32), 'payload' => $oldPayload, 'featureHash' => advertFeatureHash($feature), 'configRevision' => 1, 'preparedAt' => $now, 'promotedAt' => $now, 'approved' => true, 'image' => $image];
    file_put_contents($file, $jpeg);
    $partial['usage'] = $legacy['usage']; file_put_contents($root . '/state.json', json_encode($partial));
    $repaired = advertGetAdmin($environment);
    $check($repaired['config']['image']['complexity'] === 'medium' && $repaired['draft']['image']['complexity'] === 'medium' && $repaired['usage'] === $partial['usage'], 'Known partial schema2 complexity backfill preserves counters');
    $check($repaired['config']['image']['layouts'] === ['poster', 'split', 'image-led'] && $repaired['config']['image']['maxHeadlineWords'] === 5, 'Schema3 adds bounded composition defaults');
    $check($repaired['current'] === $partial['current'] && is_file($file), 'Schema3 retains old payload without composition and its image unchanged');
    $bad = $c; $bad['image']['layouts'] = []; $fails(fn() => advertValidateConfig($bad));
    $bad = $c; $bad['image']['layouts'] = ['poster', 'poster']; $fails(fn() => advertValidateConfig($bad));
    $bad = $c; $bad['image']['maxHeadlineWords'] = 1; $fails(fn() => advertValidateConfig($bad));
    echo json_encode(['passed' => $checks, 'providerCalls' => 0]), PHP_EOL;
} finally {
    foreach (glob($root . '/assets/*') ?: [] as $file) if (is_file($file)) unlink($file);
    if (is_dir($root . '/assets')) rmdir($root . '/assets');
    foreach (['state.json', 'state.lock'] as $name) if (is_file($root . '/' . $name)) unlink($root . '/' . $name);
    if (is_dir($root)) rmdir($root);
}
